1	"use client";
2	
3	import type { BalancedPerspectivesResponse } from "@/app/lib/types/artifacts";
4	import { mergeStreamingPreview } from "@/app/lib/utils/mergeStreamingPreview";
5	import ArtifactPanelShell, { type ArtifactEditingProps, type StalenessProps } from "./ArtifactPanelShell";
6	import EditableSection from "@/app/components/features/output-editing/EditableSection";
7	import CollapsibleSection from "@/app/components/ui/CollapsibleSection";
8	import { useFieldUpdaters } from "@/app/hooks/useFieldUpdaters";
9	
10	type BalancedPerspectivesPanelProps = {
11	  balancedPerspectives: BalancedPerspectivesResponse["balancedPerspectives"] | null;
12	  /** Partial map data from streaming (partial-JSON parsed) */
13	  streamingPreview?: BalancedPerspectivesResponse["balancedPerspectives"] | null;
14	  loading?: boolean;
15	  onContentChange?: (json: string) => void;
16	} & ArtifactEditingProps & StalenessProps;
17	
18	export default function BalancedPerspectivesPanel({
19	  balancedPerspectives, streamingPreview, loading,
20	  onContentChange, onAiEdit, editing, editWaitEstimate,
21	  isStale, onRegenerate,
22	}: BalancedPerspectivesPanelProps) {
23	  const { updateField, updateArrayItem } = useFieldUpdaters(balancedPerspectives, onContentChange);
24	
25	  const { displayData: displayMap, hasDisplayData } = mergeStreamingPreview(
26	    balancedPerspectives, streamingPreview,
27	    (d) => (d.perspectives?.length ?? 0) > 0 || !!d.topic,
28	  );
29	
30	  return (
31	    <ArtifactPanelShell
32	      title="Balanced Perspectives"
33	      loading={loading && !hasDisplayData}
34	      hasData={hasDisplayData}
35	      emptyMessage="No balanced perspectives yet. Generate them from the Source panel or component detail."
36	      loadingMessage="Generating balanced perspectives..."
37	      onAiEdit={onAiEdit}
38	      editing={editing}
39	      editWaitEstimate={editWaitEstimate}
40	      isStale={isStale}
41	      onRegenerate={onRegenerate}
42	    >
43	      {hasDisplayData && displayMap && (
44	        <>
45	          {/* Topic */}
46	          {displayMap.topic && (
47	          <section>
48	            <h3 className="text-xs font-semibold uppercase tracking-wide text-[#6B6560] mb-2">Topic</h3>
49	            <EditableSection value={displayMap.topic} onChange={(v) => updateField("topic", v)}>
50	              <p className="text-sm font-medium text-[var(--ink-black)]">{displayMap.topic}</p>
51	            </EditableSection>
52	          </section>
53	          )}
54	
55	          {/* Summary */}
56	          {displayMap.summary && (
57	          <section>
58	            <h3 className="text-xs font-semibold uppercase tracking-wide text-[#6B6560] mb-2">Summary</h3>
59	            <EditableSection value={displayMap.summary} onChange={(v) => updateField("summary", v)}>
60	              <p className="text-sm text-[var(--ink-black)] leading-relaxed">{displayMap.summary}</p>
61	            </EditableSection>
62	          </section>
63	          )}
64	
65	          {/* Perspectives */}
66	          {(displayMap.perspectives?.length ?? 0) > 0 && (
67	          <CollapsibleSection title="Perspectives" defaultOpen={false} count={displayMap.perspectives?.length ?? 0}>
68	            <div className="space-y-3">
69	              {displayMap.perspectives?.map((p, i) => (
70	                <EditableSection key={p.id} value={p} onChange={(newP) => updateArrayItem("perspectives", i, newP)}>
71	                  <div className="rounded border border-[#DDD9D5] bg-white px-3 py-2 space-y-2">
72	                    <div className="flex items-center gap-2">
73	                      <span className="font-mono text-xs text-[#9A9590]">{p.id}</span>
74	                      <span className="text-sm font-medium text-[var(--ink-black)]">{p.label}</span>
75	                    </div>
76	                    <p className="text-xs text-[#6B6560]">{p.coreClaim}</p>
77	
78	                    {(p.supportingArguments?.length ?? 0) > 0 && (
79	                      <div>
80	                        <span className="text-xs font-semibold text-[#6B6560]">Supporting:</span>
81	                        <ul className="list-disc pl-5 mt-1 space-y-0.5">
82	                          {p.supportingArguments?.map((arg, j) => (
83	                            <li key={j} className="text-xs text-[#6B6560]">{arg}</li>
84	                          ))}
85	                        </ul>
86	                      </div>
87	                    )}
88	
89	                    {(p.vulnerabilities?.length ?? 0) > 0 && (
90	                      <div>
91	                        <span className="text-xs font-semibold text-amber-700">Weaknesses:</span>
92	                        <ul className="list-disc pl-5 mt-1 space-y-0.5">
93	                          {p.vulnerabilities?.map((v, j) => (
94	                            <li key={j} className="text-xs text-amber-700">{v}</li>
95	                          ))}
96	                        </ul>
97	                      </div>
98	                    )}
99	                  </div>
100	                </EditableSection>
101	              ))}
102	            </div>
103	          </CollapsibleSection>
104	          )}
105	
106	          {/* Tensions */}
107	          {(displayMap.tensions?.length ?? 0) > 0 && (
108	            <CollapsibleSection title="Tensions" defaultOpen={false} count={displayMap.tensions?.length ?? 0}>
109	              <div className="space-y-2">
110	                {displayMap.tensions?.map((t, i) => (
111	                  <EditableSection key={i} value={t} onChange={(newT) => updateArrayItem("tensions", i, newT)}>
112	                    <div className="rounded border border-red-200 bg-red-50 px-3 py-2">
113	                      {t.between && (
114	                        <div className="flex items-center gap-1 text-xs font-mono text-red-700">
115	                          <span>{t.between[0]}</span>
116	                          <span className="text-red-400">&harr;</span>
117	                          <span>{t.between[1]}</span>
118	                        </div>
119	                      )}
120	                      <p className="mt-1 text-xs text-red-800">{t.description}</p>
121	                    </div>
122	                  </EditableSection>
123	                ))}
124	              </div>
125	            </CollapsibleSection>
126	          )}
127	
128	          {/* Synthesis */}
129	          {displayMap.synthesis && (
130	          <CollapsibleSection title="Proposed Resolution" defaultOpen={false}>
131	            <EditableSection value={displayMap.synthesis} onChange={(v) => updateField("synthesis", v)}>
132	              <div className="rounded border border-green-200 bg-green-50 px-3 py-2 space-y-2">
133	                <p className="text-sm text-green-900">{displayMap.synthesis.equilibrium}</p>
134	                {(displayMap.synthesis.howAddressed?.length ?? 0) > 0 && (
135	                  <div className="space-y-1">
136	                    {displayMap.synthesis.howAddressed?.map((h) => (
137	                      <div key={h.perspectiveId} className="text-xs text-green-800">
138	                        <span className="font-mono font-semibold">{h.perspectiveId}:</span>{" "}
139	                        {h.resolution}
140	                      </div>
141	                    ))}
142	                  </div>
143	                )}
144	              </div>
145	            </EditableSection>
146	          </CollapsibleSection>
147	          )}
148	        </>
149	      )}
150	    </ArtifactPanelShell>
151	  );
152	}
