1	import { describe, it, expect } from "vitest";
2	import { buildCsp } from "./proxy";
3	
4	// Pin the CSP directive list so a refactor that weakens script-src,
5	// connect-src, frame-ancestors, or object-src fails loudly in tests rather
6	// than silently shipping. CSP changes are intentional security decisions —
7	// updating this test is the explicit acknowledgement.
8	describe("buildCsp", () => {
9	  const NONCE = "test-nonce-abc123";
10	  // Pin the production CSP explicitly so these assertions don't depend on the
11	  // ambient NODE_ENV the test runner happens to set.
12	  const csp = buildCsp(NONCE, false);
13	  const directives = csp.split("; ");
14	
15	  it("interpolates the nonce into script-src", () => {
16	    expect(directives).toContain(
17	      `script-src 'self' 'nonce-${NONCE}' 'strict-dynamic'`,
18	    );
19	  });
20	
21	  it("locks down the highest-risk directives", () => {
22	    expect(directives).toContain("default-src 'self'");
23	    expect(directives).toContain("connect-src 'self'");
24	    expect(directives).toContain("frame-ancestors 'none'");
25	    expect(directives).toContain("object-src 'none'");
26	    expect(directives).toContain("base-uri 'self'");
27	    expect(directives).toContain("form-action 'self'");
28	  });
29	
30	  it("does not allow eval, wildcards, or http: schemes in production", () => {
31	    expect(csp).not.toMatch(/'unsafe-eval'/);
32	    expect(csp).not.toMatch(/\*\s/); // wildcard source not followed by directive end
33	    expect(csp).not.toMatch(/\bhttp:\b/);
34	  });
35	
36	  it("allows 'unsafe-eval' only in development (for Next.js dev HMR/eval source maps)", () => {
37	    const devCsp = buildCsp(NONCE, true);
38	    const devScriptSrc = devCsp
39	      .split("; ")
40	      .find((d) => d.startsWith("script-src"));
41	    expect(devScriptSrc).toBe(
42	      `script-src 'self' 'nonce-${NONCE}' 'strict-dynamic' 'unsafe-eval'`,
43	    );
44	    // 'unsafe-eval' must remain scoped to script-src — never leaks elsewhere.
45	    expect(devCsp.match(/'unsafe-eval'/g)).toHaveLength(1);
46	  });
47	
48	  it("emits the directive list in stable order", () => {
49	    expect(directives.map(d => d.split(" ")[0])).toEqual([
50	      "default-src",
51	      "script-src",
52	      "style-src",
53	      "img-src",
54	      "font-src",
55	      "connect-src",
56	      "frame-ancestors",
57	      "base-uri",
58	      "object-src",
59	      "form-action",
60	    ]);
61	  });
62	});
