138	// ---------------------------------------------------------------------------
139	// Route handler
140	// ---------------------------------------------------------------------------
141	
142	export async function POST(request: NextRequest) {
143	  try {
144	    const body = (await request.json()) as Partial<EvidenceSearchRequest>;
145	
146	    if (!body.elementContent || typeof body.elementContent !== "string") {
147	      return NextResponse.json({ error: "elementContent is required" }, { status: 400 });
148	    }
149	    if (!body.artifactType || !body.elementId) {
150	      return NextResponse.json({ error: "artifactType and elementId are required" }, { status: 400 });
151	    }
152	    if (!EVIDENCE_ARTIFACT_TYPES.includes(body.artifactType as (typeof EVIDENCE_ARTIFACT_TYPES)[number])) {
153	      return NextResponse.json({ error: `artifactType must be one of: ${EVIDENCE_ARTIFACT_TYPES.join(", ")}` }, { status: 400 });
154	    }
155	
156	    // Cap element content length to avoid runaway LLM token usage
157	    const elementContent = body.elementContent.slice(0, MAX_ELEMENT_CONTENT_LENGTH);
158	
159	    // Step 1: Use the caller's edited queries when provided, else generate.
160	    const override = sanitizeQueries(body.queries);
161	    const queries =
162	      override.length > 0
163	        ? override
164	        : await generateSearchQueries(elementContent, body.contextSummary);
165	
166	    // Step 2: Search OpenAlex for all queries in parallel
167	    const queryResults = await Promise.allSettled(queries.map(searchOpenAlex));
168	    const allWorks: OpenAlexWork[] = [];
169	    for (const result of queryResults) {
170	      if (result.status === "fulfilled") {
171	        allWorks.push(...result.value);
172	      }
173	    }
174	
175	    // Step 3: Filter by relevance score, map, deduplicate, cap results
176	    // OpenAlex returns relevance_score with title_and_abstract.search filter;
177	    // drop results with very low scores (< 40% of the top result's score)
178	    // Safe to spread: allWorks holds at most PER_QUERY_RESULTS per query —
179	    // worst case MAX_OVERRIDE_QUERIES (5) queries on the override path (25),
180	    // fewer on the LLM path (≤3 queries → 15). Well under the arg-count limit.
181	    const topScore = Math.max(...allWorks.map((w) => w.relevance_score ?? 0), 1);
182	    const relevanceThreshold = topScore * 0.4;
183	    const relevantWorks = allWorks.filter(
184	      (w) => (w.relevance_score ?? 0) >= relevanceThreshold,
185	    );
186	    const papers = deduplicatePapers(relevantWorks.map(mapOpenAlexWork)).slice(0, MAX_RESULTS);
187	
188	    const response: EvidenceSearchResponse = { queries, papers };
189	    return NextResponse.json(response);
190	  } catch (err) {
191	    if (err instanceof OpenRouterError) {
192	      return NextResponse.json(
193	        { error: err.message, details: err.details },
194	        { status: 502 },
195	      );
196	    }
197	    const message = err instanceof Error ? err.message : "Unknown error";
198	    console.error("[evidence-search] Error:", message);
199	    return NextResponse.json({ error: message }, { status: 500 });
200	  }
201	}
