1	/**
2	 * Zustand store for evidence search results.
3	 *
4	 * Separate from the main workspaceStore because evidence is metadata *about*
5	 * artifacts, not an artifact itself — it doesn't participate in artifact
6	 * versioning, undo/redo, or generation provenance.
7	 *
8	 * Persists to localStorage with debounced writes (see the debounced storage
9	 * adapter below) to avoid excessive serialization on rapid updates.
10	 */
11	
12	import { create } from "zustand";
13	import { persist, createJSONStorage } from "zustand/middleware";
14	import type { EvidencePaper, EvidenceSlot, PaperScore, OverlapAnalysis, IntegrationProposal } from "@/app/lib/types/evidence";
15	
16	// ---------------------------------------------------------------------------
17	// Debounced localStorage adapter (same pattern as workspaceStore)
18	// ---------------------------------------------------------------------------
19	
20	function createDebouncedStorage() {
21	  let pending: ReturnType<typeof setTimeout> | null = null;
22	  return {
23	    getItem: (name: string) => localStorage.getItem(name),
24	    setItem: (name: string, value: string) => {
25	      if (pending) clearTimeout(pending);
26	      pending = setTimeout(() => {
27	        try {
28	          localStorage.setItem(name, value);
29	        } catch (e) {
30	          console.warn("Failed to persist evidence store:", e);
31	        }
32	        pending = null;
33	      }, 300);
34	    },
35	    removeItem: (name: string) => {
36	      if (pending) clearTimeout(pending);
37	      pending = null;
38	      localStorage.removeItem(name);
39	    },
40	  };
41	}
42	
43	// Hoist so the persist middleware always uses the same adapter instance.
44	// Safe at module scope because the adapter's methods are only invoked via the
45	// persist middleware's `storage` config, which is guarded by
46	// `typeof window !== "undefined"` in the persist config below. During SSR,
47	// `storage` is `undefined` so the adapter is never called.
48	const debouncedStorage = createDebouncedStorage();
49	
50	// ---------------------------------------------------------------------------
51	// Store shape
52	// ---------------------------------------------------------------------------
53	
54	interface EvidenceState {
55	  /** Evidence slots keyed by "artifactType::elementId" */
56	  slots: Record<string, EvidenceSlot>;
57	  /** Per-element overlap analysis results */
58	  overlap: Record<string, OverlapAnalysis>;
59	  /** Per-element integration proposals */
60	  proposals: Record<string, IntegrationProposal[]>;
61	  /** Per-element loading state (search or scoring) */
62	  loading: Record<string, boolean>;
63	  /** Per-element scoring loading state */
64	  scoring: Record<string, boolean>;
65	  /** Per-element overlap analysis loading state */
66	  analyzing: Record<string, boolean>;
67	  /** Per-element integration loading state */
68	  integrating: Record<string, boolean>;
69	  /** Per-element search error messages */
70	  errors: Record<string, string>;
71	  /** Per-element scoring error messages (separate channel from search so the
72	   *  two operations don't clear or mask each other's errors) */
73	  scoringErrors: Record<string, string>;
74	}
75	
76	interface EvidenceActions {
77	  setEvidence: (key: string, slot: EvidenceSlot) => void;
78	  setLoading: (key: string, loading: boolean) => void;
79	  setScoring: (key: string, scoring: boolean) => void;
80	  setAnalyzing: (key: string, analyzing: boolean) => void;
81	  setIntegrating: (key: string, integrating: boolean) => void;
82	  setError: (key: string, error: string | null) => void;
83	  setScoringError: (key: string, error: string | null) => void;
84	  /** Apply LLM scores to papers in a slot */
85	  applyScores: (key: string, scores: PaperScore[]) => void;
86	  /** Apply overlap analysis results */
87	  applyOverlap: (key: string, analysis: OverlapAnalysis) => void;
88	  /** Store integration proposals */
89	  setProposals: (key: string, proposals: IntegrationProposal[]) => void;
90	  /** Update decision on a single proposal */
91	  setProposalDecision: (key: string, proposalId: string, decision: boolean) => void;
92	  /** Clear all proposals for a slot */
93	  clearProposals: (key: string) => void;
94	  /** Merge freshly-searched papers into an existing slot (dedup by id,
95	   *  existing papers win) and replace the slot's query list. */
96	  mergeEvidence: (key: string, queries: string[], newPapers: EvidencePaper[]) => void;
97	  /** Soft-prune a paper (status -> pruned). */
98	  prunePaper: (key: string, openAlexId: string) => void;
99	  /** Restore a pruned paper (status -> evaluated if scored, else retrieved). */
100	  restorePaper: (key: string, openAlexId: string) => void;
101	  clearEvidence: (key: string) => void;
102	  clearAll: () => void;
103	}
104	
105	const DEFAULT_STATE: EvidenceState = {
106	  slots: {},
107	  overlap: {},
108	  proposals: {},
109	  loading: {},
110	  scoring: {},
111	  analyzing: {},
112	  integrating: {},
113	  errors: {},
114	  scoringErrors: {},
115	};
116	
117	/** Migrate persisted evidence state across store versions.
118	 *  v0 -> v1: backfill `status` on papers (evaluated if already scored, else
119	 *  retrieved). Exported for direct unit testing. */
120	export function migrateEvidenceState(persistedState: unknown, version: number): unknown {
121	  const state = persistedState as { slots?: Record<string, EvidenceSlot> } | null;
122	  if (!state || typeof state !== "object" || !state.slots) return persistedState;
123	  if (version >= 1) return persistedState;
124	
125	  const slots: Record<string, EvidenceSlot> = {};
126	  for (const [key, slot] of Object.entries(state.slots)) {
127	    slots[key] = {
128	      ...slot,
129	      papers: (Array.isArray(slot.papers) ? slot.papers : []).map((p) => {
130	        const existing = (p as Partial<EvidencePaper>).status;
131	        return {
132	          ...p,
133	          status: existing ?? (p.reliability ? "evaluated" : "retrieved"),
134	        } as EvidencePaper;
135	      }),
136	    };
137	  }
138	  return { ...state, slots };
139	}
