2	 * Corpus feature flag (DD-009 sub-task S1).
3	 *
4	 * DEFAULT OFF and DEV-ONLY. In S1 there is no localStorage->corpus migration
5	 * (that is S4), so enabling this starts from an EMPTY corpus and does not carry
6	 * existing localStorage work over. It exists only to let developers exercise the
7	 * OPFS path; it must not be turned on for end users until S4 ships migration.
8	 *
9	 * Enable via either the build-time env `NEXT_PUBLIC_CORPUS_FS=1` or, at runtime
10	 * in a dev browser, `localStorage.setItem("corpus-fs-enabled", "1")`.
11	 */
12	
13	export const CORPUS_FLAG_KEY = "corpus-fs-enabled";
14	
15	export function isCorpusEnabled(): boolean {
16	  // Hard production guard: because S1 has no migration, enabling the corpus path
17	  // swaps persistence to an empty corpus and existing localStorage work appears
18	  // to vanish. Refuse to activate in a production build so the dev flag can never
19	  // become an end-user data-loss footgun (security review C2). Remove this guard
20	  // only when S4 ships migration and the flag becomes a real, safe rollout knob.
21	  if (typeof process !== "undefined" && process.env?.NODE_ENV === "production") return false;
22	
23	  if (typeof process !== "undefined" && process.env?.NEXT_PUBLIC_CORPUS_FS === "1") return true;
24	  if (typeof window !== "undefined") {
25	    try {
26	      return window.localStorage.getItem(CORPUS_FLAG_KEY) === "1";
27	    } catch {
28	      return false;
29	    }
30	  }
31	  return false;
32	}
