18	  const updateField = useCallback((key: string, value: unknown) => {
19	    if (!dataRef.current || !onContentChange) return;
20	    // eslint-disable-next-line @typescript-eslint/no-explicit-any -- dynamic key access on a known-structured object
21	    if ((dataRef.current as any)[key] === value) return;
22	    onContentChange(JSON.stringify({ ...dataRef.current, [key]: value }));
