29	
30	  const isString = typeof value === "string";
31	
32	  // Close editor if value changes externally (e.g. whole-document AI rewrite).
33	  // Uses a ref to track the previous serialized value so we only close on
34	  // genuine external changes, not after the user's own save.
35	  const prevSerializedRef = useRef<string | null>(null);
36	  const serialized = editing ? JSON.stringify(value) : null;
37	  useEffect(() => {
38	    if (!editing || serialized === null) return;
39	    if (prevSerializedRef.current !== null && prevSerializedRef.current !== serialized) {
40	      setEditing(false);
41	    }
42	    prevSerializedRef.current = serialized;
43	  }, [serialized, editing]);
44	
45	  const startEditing = useCallback(() => {
