47	    setEditText(text);
48	    setParseError(null);
49	    setEditing(true);
50	  }, [value, isString]);
51	
52	  const handleSave = useCallback(() => {
53	    if (isString) {
54	      onChange(editText);
55	    } else {
56	      try {
57	        onChange(JSON.parse(editText));
58	        setParseError(null);
59	      } catch {
60	        setParseError("Invalid JSON");
61	        return;
62	      }
63	    }
64	    setEditing(false);
65	  }, [editText, onChange, isString]);
66	
67	  const handleCancel = useCallback(() => {
68	    setEditing(false);
69	    setParseError(null);
70	  }, []);
71	
72	  const handleAiEdit = useCallback(async () => {
73	    if (!aiInstruction.trim()) return;
